<form method="post" enctype="multipart/form-data" action="{{ url('/admin/sections' . ($section ? '/'.$section->id : '')) }}">@csrf @if($section) @method('PUT') @endif<div class="columns"><label>Section type<select name="type">@foreach(['hero','ticker','collection','story','custom'] as $type)<option @selected($section?->type === $type)>{{ $type }}</option>@endforeach</select></label><label>Order<input type="number" name="sort_order" min="0" max="10000" value="{{ $section?->sort_order ?? 50 }}" required></label></div><div class="columns">@foreach(['eyebrow','heading','highlight','body','body2','button','link','secondary','secondary_link','ring_name','badge','hint','item1','item2','item3','note'] as $field)<label>{{ ucfirst(str_replace('_',' ', $field)) }}@if(in_array($field, ['body','body2','note']))<textarea name="content[{{ $field }}]" rows="3">{{ $section?->content[$field] ?? '' }}</textarea>@else<input name="content[{{ $field }}]" value="{{ $section?->content[$field] ?? '' }}">@endif</label>@endforeach</div><p>Hero uses heading, highlight, body, buttons, badge and ring labels. Ticker uses items 1–3. Collection uses eyebrow, heading and note. Story/custom use heading, body, body2 and button. Links accept local paths or section anchors.</p><label>Section photo (JPG, PNG or WebP, up to 4 MB, hero photo replaces the 3D ring)<input type="file" name="image_upload" accept="image/png,image/jpeg,image/webp"></label>@if($section?->content['image'] ?? null)<img class="preview-image" src="{{ asset('storage/'.$section->content['image']) }}" alt="Section photo"><label class="check"><input type="checkbox" name="remove_image" value="1">Remove photo</label>@endif<label class="check"><input type="checkbox" name="active" value="1" @checked($section?->active ?? true)>Visible on homepage</label><button class="cta">PUBLISH SECTION</button></form>